"""Read back the Markdown cards generated by the catalogue CLI."""

from __future__ import annotations

import re
import shutil
import subprocess
import sys
from pathlib import Path
from urllib.parse import unquote

import pytest
import yaml

from gps_kataster_obiektow_tatr.coordinates import wgs84_to_1992

REPO_ROOT = Path(__file__).resolve().parents[1]
FIXTURES = Path(__file__).parent / "fixtures"


@pytest.fixture
def data_dir(tmp_path: Path) -> Path:
    data = tmp_path / "źródło danych"
    fixtures = {
        "objects/KSW/KSW-0001.yml": "valid-object.yml",
        "objects/KSW/KSW-0002.yml": "object-with-tpn-globalid.yml",
        "objects/KSW/KSW-0003.yml": "object-with-manual-best.yml",
        "caves/C-0001.yml": "valid-cave.yml",
        "caves/C-0002.yml": "cave-with-pig-and-nr-inwent.yml",
    }
    for path, fixture in fixtures.items():
        target = data / path
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(FIXTURES / fixture, target)
        if path.startswith("objects/"):
            # The schema fixtures contain illustrative, unprojected coordinates.
            record = yaml.safe_load(target.read_text())
            for measurement in record["measurements"]:
                projected = wgs84_to_1992(measurement["lat"], measurement["lon"])
                measurement.update(x_1992=projected.x_1992, y_1992=projected.y_1992)
            target.write_text(yaml.safe_dump(record, sort_keys=False))
    (data / "relations").mkdir()
    return data


def _run(data: Path, output: Path) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [
            sys.executable,
            str(REPO_ROOT / "scripts/build_catalog_cards.py"),
            "--data-dir",
            str(data),
            "--output-dir",
            str(output),
        ],
        cwd=data.parent,
        capture_output=True,
        text=True,
        check=False,
    )


def _contents(directory: Path) -> dict[str, bytes]:
    return {
        path.relative_to(directory).as_posix(): path.read_bytes()
        for path in directory.rglob("*")
        if path.is_file()
    }


def test_cards_show_sources_and_saved_best_with_source_order_history(
    data_dir: Path, tmp_path: Path
) -> None:
    output = tmp_path / "catalog"
    manual = data_dir / "objects/KSW/KSW-0003.yml"
    record = yaml.safe_load(manual.read_text())
    record["name_local"] = "Jaskinia [A] | <tag> *otwór*"
    first, second = record["measurements"]
    second["observed_at"] = "2026-05-16T11:10:00+02:00"
    record["measurements"].insert(
        1,
        {
            **first,
            "id": "m-003",
            "observed_at": "2026-05-14T09:10:00Z",
            "observed_date": "2026-05-14",
        },
    )
    manual.write_text(yaml.safe_dump(record, sort_keys=False, allow_unicode=True))
    source = _contents(data_dir)

    result = _run(data_dir, output)
    assert result.returncode == 0, result.stderr
    assert set(_contents(output)) == {
        "index.md",
        "objects/KSW-0001.md",
        "objects/KSW-0002.md",
        "objects/KSW-0003.md",
        "caves/C-0001.md",
        "caves/C-0002.md",
    }
    index = (output / "index.md").read_text()
    assert "](objects/KSW-0003.md)" in index
    assert "](caves/C-0002.md)" in index

    card = (output / "objects/KSW-0003.md").read_text()
    assert r"Jaskinia \[A\] \| \<tag\> \*otwór\*" in card
    assert "](../caves/C-0001.md)" in card
    assert "`objects/KSW/KSW-0003.yml`" in card
    best, history = card.split("## Historia pomiarów")
    assert "m-001" in best and "manual" in best
    assert "Pomiar m-001 ma wyraznie lepsza dokladnosc" in best
    assert "Wynik reguły automatycznej" not in best
    assert "Ostrzeżenie" not in best
    assert [
        line.split(" | ", 1)[0].removeprefix("| ")
        for line in history.splitlines()
        if line.startswith("| m-")
    ] == ["m-001", "m-003", "m-002"]
    assert "2026-05-16T11:10:00+02:00" in history
    assert "teren:2026-05-16:smartfon" in history
    assert "Nowszy, ale mniej dokladny pomiar kontrolny" in history

    automatic = (output / "objects/KSW-0002.md").read_text()
    assert "auto" in automatic and "m-001" in automatic
    assert "Dokładność pozioma | nieznana" in automatic
    assert "Dokładność pionowa | nieznana" in automatic
    assert "Datum wysokości | nieznane" in automatic
    assert "71432220-CA17-4420-ACC8-394596EDF79F" in automatic

    cave = (output / "caves/C-0002.md").read_text()
    assert "](../objects/KSW-0002.md)" in cave
    assert "https://jaskiniepolski.pgi.gov.pl/Details/Information/1094" in cave
    assert "T.D-08.07" in cave

    first_build = _contents(output)
    result = _run(data_dir, output)
    assert result.returncode == 0, result.stderr
    assert _contents(output) == first_build
    assert _contents(data_dir) == source


@pytest.mark.parametrize("reason", [None, "Opis zapisany przez operatora."])
def test_auto_card_discloses_mismatch_without_changing_saved_best(
    data_dir: Path, tmp_path: Path, reason: str | None
) -> None:
    source_path = data_dir / "objects/KSW/KSW-0003.yml"
    record = yaml.safe_load(source_path.read_text())
    record["best_measurement"].update(mode="auto", reason=reason)
    source_path.write_text(yaml.safe_dump(record, sort_keys=False))
    source = _contents(data_dir)
    output = tmp_path / "catalog"

    result = _run(data_dir, output)
    assert result.returncode == 0, result.stderr
    best = (output / "objects/KSW-0003.md").read_text().split("## Historia pomiarów")[0]
    assert "- Pomiar — m-001" in best
    assert "- Wynik reguły automatycznej — m-002" in best
    assert "Ostrzeżenie" in best
    assert "Reguła automatyczna uwzględnia" not in best
    if reason:
        assert reason in best
    assert _contents(data_dir) == source


def test_auto_card_explains_matching_selection_without_mismatch_warning(
    data_dir: Path, tmp_path: Path
) -> None:
    source_path = data_dir / "objects/KSW/KSW-0003.yml"
    record = yaml.safe_load(source_path.read_text())
    record["best_measurement"].update(mode="auto", measurement_id="m-002", reason=None)
    source_path.write_text(yaml.safe_dump(record, sort_keys=False))
    output = tmp_path / "catalog"

    result = _run(data_dir, output)
    assert result.returncode == 0, result.stderr
    best = (output / "objects/KSW-0003.md").read_text().split("## Historia pomiarów")[0]
    assert "- Pomiar — m-002" in best
    assert "Reguła automatyczna uwzględnia" in best
    assert "Ostrzeżenie" not in best


def test_catalog_links_work_after_artifact_is_extracted(data_dir: Path, tmp_path: Path) -> None:
    output = tmp_path / "catalog"
    result = _run(data_dir, output)
    assert result.returncode == 0, result.stderr
    extracted = tmp_path / "download" / "nested" / "catalog"
    shutil.copytree(output, extracted)

    links = []
    for page in extracted.rglob("*.md"):
        for href in re.findall(r"\]\(([^)]+)\)", page.read_text()):
            if "://" not in href:
                target = (page.parent / unquote(href)).resolve()
                assert target.is_relative_to(extracted.resolve())
                assert target.is_file()
                links.append(target)
    assert extracted / "index.md" in links


def test_invalid_references_leave_previous_catalog_untouched(
    data_dir: Path, tmp_path: Path
) -> None:
    output = tmp_path / "catalog"
    result = _run(data_dir, output)
    assert result.returncode == 0, result.stderr
    previous = _contents(output)
    cave = data_dir / "caves/C-0002.yml"
    cave.write_text(cave.read_text().replace("KSW-0002", "KSW-0999"))
    source = _contents(data_dir)

    result = _run(data_dir, output)
    assert result.returncode == 1
    assert "KSW-0999" in result.stderr
    assert _contents(output) == previous
    assert _contents(data_dir) == source


def test_rebuild_preserves_files_added_by_user(data_dir: Path, tmp_path: Path) -> None:
    output = tmp_path / "catalog"
    result = _run(data_dir, output)
    assert result.returncode == 0, result.stderr
    (output / "objects" / "moje-notatki.md").write_text("Notatka spoza generatora.")
    previous = _contents(output)

    result = _run(data_dir, output)
    assert result.returncode == 1
    assert "zawiera inne dane" in result.stderr
    assert _contents(output) == previous


@pytest.mark.parametrize("relative_path", [".", "objects", "caves/generated", ".."])
def test_cli_rejects_output_overlapping_data(data_dir: Path, relative_path: str) -> None:
    source = _contents(data_dir)
    result = _run(data_dir, data_dir / relative_path)

    assert result.returncode == 1
    assert "koliduje" in result.stderr
    assert _contents(data_dir) == source


def test_symlinked_output_parent_cannot_write_into_sources(data_dir: Path, tmp_path: Path) -> None:
    source = _contents(data_dir)
    alias = tmp_path / "source-alias"
    alias.symlink_to(data_dir, target_is_directory=True)

    result = _run(data_dir, alias / "generated")
    assert result.returncode == 1
    assert "koliduje" in result.stderr
    assert not (data_dir / "generated").exists()
    assert _contents(data_dir) == source


def test_failed_publication_restores_previous_catalog(
    data_dir: Path, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    from gps_kataster_obiektow_tatr.catalog_cards import build_catalog_cards

    output = tmp_path / "catalog"
    build_catalog_cards(data_dir=data_dir, output_dir=output)
    previous = _contents(output)
    cave = data_dir / "caves/C-0001.yml"
    cave.write_text(cave.read_text().replace("Jaskinia testowa", "Jaskinia po korekcie"))
    original_rename = Path.rename
    attempts = []

    def rename(source: Path, destination: Path) -> Path:
        if destination == output.resolve():
            attempts.append(source)
            if len(attempts) == 1:
                raise OSError("publikacja przerwana")
        return original_rename(source, destination)

    monkeypatch.setattr(Path, "rename", rename)
    with pytest.raises(OSError, match="publikacja przerwana"):
        build_catalog_cards(data_dir=data_dir, output_dir=output)
    assert len(attempts) == 2
    assert _contents(output) == previous
